# Edamam Recipe API
import requests

EDAMAM_APP_ID = "b79327d05b8e5b838ad6cfd9576b30b6"
EDAMAM_APP_KEY = "your_app_key"
BASE_URL = "https://api.edamam.com/api/recipes/v2"

def search_edamam_recipes(query, diet=None, health=None, cuisine_type=None):
    """Search recipes with Edamam"""
    params = {
        "type": "public",
        "q": query,
        "app_id": EDAMAM_APP_ID,
        "app_key": EDAMAM_APP_KEY,
        "random": True
    }

    if diet:
        params["diet"] = diet
    if health:
        params["health"] = health
    if cuisine_type:
        params["cuisineType"] = cuisine_type

    response = requests.get(BASE_URL, params=params)
    return response.json()

def get_recipe_by_uri(recipe_uri):
    """Get recipe by URI"""
    response = requests.get(
        BASE_URL,
        params={
            "type": "public",
            "app_id": EDAMAM_APP_ID,
            "app_key": EDAMAM_APP_KEY,
            "r": recipe_uri
        }
    )
    return response.json()
